int ring_index = 0;
spawn = &spawns[builder.count];
builder.count += 12;
while (ring_index < 12) {
    float angle = (float)ring_index * 0.52359879f;
    spawn->pos.set(
        (float)cos(angle) * 178.0f,
        (float)sin(angle) * 178.0f);
    spawn->pos.add(512.0f);
    spawn->heading = angle;
    spawn->set_spawn(
        SPAWN_ID_SPIDER_SMALL_BLUE_40,
        8000,
        1);
    ++spawn;
    ++ring_index;
}

